head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gTrnsType;
scwin.gAllChk = false;
scwin.vScrenID = "ULDSTF30320.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    //fn_getPrevBzDt(dts_AgBzDd);
    //setObjectValue(edt_SDATE,  dts_AgBzDd.NameValue(0, "CALND_DD")); 

    var ToDay = $c.ut.cGetToday2();
    $c.stf.setObjectValue(edt_SDATE, ToDay);
};
scwin.initPage = function() {

};
scwin.fn_Confirm = function() {
    // opener에 값 선택된 값 전달.

    var total = 0;
    for (var i = 1; i <= dts_TrstkSubmit.getTotalRow(); i++) {
        var chk = dts_TrstkSubmit.getCellData(i, "CHECK");
        if (chk == "T" || chk == "1") total++;
    }
    if (total == 0) {
        $c.win.alert("수신자를 선택하세요.");
        return false;
    }
    frame.opener.grd_Receiver.setBroadcast(false);
    var j = 1 + frame.opener.dts_Receiver.getTotalRow();
    for (var i = 1; i <= dts_TrstkSubmit.getTotalRow(); i++) {
        var chk = dts_TrstkSubmit.getCellData(i, "CHECK");
        var vLength = dts_TrstkSubmit.getCellData(i, "ENCRYP_ORDERER_CELLPHONE_NO").length;
        if (vLength > 0 && (chk == "T" || chk == "1")) {
            frame.opener.dts_Receiver.AddRow();
            frame.opener.dts_Receiver.setCellData(j, "CHECK", "T");
            frame.opener.dts_Receiver.setCellData(j, "COM_ABBRV", dts_TrstkSubmit.getCellData(i, "COM_ABBRV"));
            frame.opener.dts_Receiver.setCellData(j, "CHRG_NM", dts_TrstkSubmit.getCellData(i, "ORDERER_NM"));
            frame.opener.dts_Receiver.setCellData(j, "CELLPHONE_NO", dts_TrstkSubmit.getCellData(i, "ENCRYP_ORDERER_CELLPHONE_NO"));
            frame.opener.dts_Receiver.setCellData(j, "ISUR_CD", dts_TrstkSubmit.getCellData(i, "ISUR_CD"));
            frame.opener.dts_Receiver.setCellData(j, "EMAIL", dts_TrstkSubmit.getCellData(i, "TRSTK_APPL_DD"));
            //frame.opener.dts_Receiver.NameString(j, "EMAIL") = "-"		

            j++;
        }
    }
    //frame.opener.grd_TrstkSubmit.AutoResizeAllCol(true);
    frame.opener.grd_Receiver.setBroadcast(true);
    frame.opener.fn_RowCount();
    return true;
};
scwin.fn_SelectAll = function() {
    grd_TrstkSubmit.Redraw = false;
    if (scwin.gAllChk == false) {
        // 현재상태가 false이면 전체선택을 클릭릭한것

        scwin.gAllChk = true;
        for (var i = 0; i < dts_TrstkSubmit.getTotalRow(); i++) {
            dts_TrstkSubmit.setCellData(i + 1, "CHECK", "T");
        }
        btn_SelectedAll.setValue("전체해제");
    } else {
        // 현재상태가  true이면 전체선택을 클릭한것
        scwin.gAllChk = false;
        for (var i = 0; i < dts_TrstkSubmit.getTotalRow(); i++) {
            dts_TrstkSubmit.setCellData(i + 1, "CHECK", "F");
        }
        btn_SelectedAll.setValue("전체선택");
    }
    grd_TrstkSubmit.Redraw = true;
};
scwin.fn_Search = function() {
    var msg;
    if ($c.stf.getObjectValue(edt_SDATE) == "") {
        msg = $c.stf.getMessageParam("MSG-A005", "신청일자");
        $c.win.alert(msg);
        edt_SDATE.focus();
        return false;
    }

    // 초기화 
    scwin.gAllChk == false;
    btn_SelectedAll.setValue("전체선택");
    var url = "";

    // 자사주 신청내역조회
    url = "/NoteMgt.do?method=listTrstkSubmit";
    url += "&SDATE=" + $c.stf.getObjectValue(edt_SDATE);
    url += "&SPOT_ISU_TRD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MKT_ID);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    $c.cm.ShowWin(grd_TrstkSubmit);
    dts_TrstkSubmit.DataID = encodeURI(url);
    dts_TrstkSubmit.Reset();
};


// 전 영업일 구하기
scwin.fn_getPrevBzDt = function(dtsObj) {
    var url = "/NoteMgt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=getPrevBzDt";
    url += "&inputMessageId=BIZSPT_NOTE_PREVBZDT&outputMessageId=BIZSPT_NOTE_PREVBZDT";
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
};



// 종목 총 건수 구하기
scwin.fn_getIsuCnt = function(dtsObj) {
    var url = "/NoteMgt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=getIsuCnt";
    url += "&APPL_DT=" + $c.stf.getObjectValue(edt_SDATE);
    url += "&MKT_ID=" + $c.stf.getObjectValue(rdo_MKT_ID);
    url += "&inputMessageId=BIZSPT_NOTE_ISUCNT&outputMessageId=BIZSPT_NOTE_ISUCNT";
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Confirm_onclick = async function() {
    if (scwin.fn_Confirm() == true) {
        await $c.frame.CloseFrame();
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.dts_TrstkSubmit_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(txb_totCnt, "총건수 : " + rowcount);
    $c.cm.CloseWin(rowcount, grd_TrstkSubmit);
    scwin.fn_getIsuCnt(dts_IsuCnt);
    $c.stf.setObjectValue(txb_cnt, dts_IsuCnt.getCellData(0, "ISU_CNT"));
    $c.stf.setObjectValue(txb_isu_cnt, "종목 총건수 : " + $c.stf.getObjectValue(txb_cnt));
};
scwin.dts_TrstkSubmit_OnLoadError = function() {
    $c.stf.alert_error(dts_TrstkSubmit);
};
scwin.btn_SelectedAll_onclick = function() {
    scwin.fn_SelectAll();
};
scwin.btn_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    scwin.initPage();
    $c.stf.showObj(txb_cnt, false);
    $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
    if (scwin.gLdMktTp == '1' || scwin.gLdMktTp == '2' || scwin.gLdMktTp == '6') {
        $c.stf.showObj(panel_mkt, false);
    }
    scwin.fn_Search();
};
